  "recovered_c": "uint64_t fn_01(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (len == 0) {\n    return 0;\n  }\n\n  uint32_t crc = 0xFFFFFFFF;\n  for (size_t i = 0; i < len; i++) {\n    crc ^= in[i];\n    for (int j = 0; j < 8; j++) {\n      crc = -(crc & 1) & 0xEDB88320 ^ crc >> 1;\n    }\n  }\n\n  return ~crc;\n}"
}
